package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/ast"
	"reflect"
	"sort"
	"strings"
	"time"
)

// header is the first thing of the generated file.
const header = `// Code generated by cmd/gen-ts from the Go wire types of hosts/client, core/store, features/memory and product.
// DO NOT EDIT: change the Go type (or cmd/gen-ts/types.go) and run ` + "`make gen`" + `.
// A Go test (go test ./cmd/gen-ts) fails when this file is stale.
`

// root is a Go type the web app uses, under the name it has in TypeScript.
type root struct {
	name  string
	value any
}

// enum is a string union; its values come from the Go constants where they exist.
type enum struct {
	name   string
	values []string
}

// extra is a hand-written declaration the generator cannot derive from a struct (a map the server builds).
type extra struct {
	name string
	text string
}

// generator turns Go types into TypeScript declarations.
//
// The mapping follows encoding/json: field names and omitempty come from the json tag, embedded structs are
// flattened, time.Time is a string, json.RawMessage and interfaces are unknown, []byte is a (base64) string, a
// map is a Record, a pointer is nullable. A slice or map field without omitempty is typed as non-null: the
// servers of this repository send [] and {}, never null, for them. Where the Go type is looser than what is
// sent (a map[string]any) or stricter in meaning than it says (a string that is one of a few values),
// overrides give the TypeScript type of one field, keyed by "pkg.GoType.jsonName".
type generator struct {
	enums     []enum
	extras    []extra
	overrides map[string]string

	names   map[reflect.Type]string // emitted struct types
	decls   map[string]string       // TypeScript name -> declaration
	queue   []reflect.Type
	used    map[string]bool // overrides that matched a field
	pending map[string]reflect.Type
}

func newGenerator(enums []enum, extras []extra, overrides map[string]string) *generator {
	return &generator{enums: enums, extras: extras, overrides: overrides, names: map[reflect.Type]string{}, decls: map[string]string{},
		used: map[string]bool{}, pending: map[string]reflect.Type{}}
}

// generate returns the whole file for the roots.
func (g *generator) generate(roots []root) ([]byte, error) {
	for _, r := range roots {
		t := reflect.TypeOf(r.value)
		if t.Kind() != reflect.Struct {
			return nil, fmt.Errorf("root %s is %s, not a struct", r.name, t)
		}
		if err := g.name(t, r.name); err != nil {
			return nil, err
		}
	}
	for len(g.queue) > 0 {
		t := g.queue[0]
		g.queue = g.queue[1:]
		decl, err := g.declare(t)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", t, err)
		}
		g.decls[g.names[t]] = decl
	}
	for _, e := range g.enums {
		if _, dup := g.decls[e.name]; dup {
			return nil, fmt.Errorf("enum %s collides with a type of the same name", e.name)
		}
		g.decls[e.name] = fmt.Sprintf("export type %s = %s;\n", e.name, union(e.values))
	}
	for _, x := range g.extras {
		if _, dup := g.decls[x.name]; dup {
			return nil, fmt.Errorf("extra %s collides with a type of the same name", x.name)
		}
		g.decls[x.name] = x.text
	}
	var unused []string
	for k := range g.overrides {
		if !g.used[k] {
			unused = append(unused, k)
		}
	}
	if len(unused) > 0 {
		sort.Strings(unused)
		return nil, fmt.Errorf("overrides match no field (stale?): %s", strings.Join(unused, ", "))
	}

	names := make([]string, 0, len(g.decls))
	for n := range g.decls {
		names = append(names, n)
	}
	sort.Strings(names)
	var b bytes.Buffer
	b.WriteString(header)
	for _, n := range names {
		b.WriteString("\n")
		b.WriteString(g.decls[n])
	}
	return b.Bytes(), nil
}

func union(values []string) string {
	q := make([]string, len(values))
	for i, v := range values {
		q[i] = fmt.Sprintf("%q", v)
	}
	return strings.Join(q, " | ")
}

// name registers t under name and queues it for emission.
func (g *generator) name(t reflect.Type, name string) error {
	if have, ok := g.names[t]; ok {
		if have != name {
			return fmt.Errorf("%s is named both %s and %s", t, have, name)
		}
		return nil
	}
	if other, ok := g.pending[name]; ok && other != t {
		return fmt.Errorf("two Go types are named %s: %s and %s", name, other, t)
	}
	g.pending[name] = t
	g.names[t] = name
	g.queue = append(g.queue, t)
	return nil
}

type field struct {
	name     string // json name
	typ      reflect.Type
	optional bool
	owner    string // declaring Go type, for overrides
	depth    int
}

// fields lists the json fields of struct t, with embedded structs flattened as encoding/json does: a field
// of a shallower struct hides one of the same name deeper down.
func fields(t reflect.Type) []field {
	var out []field
	index := map[string]int{}
	var walk func(t reflect.Type, depth int)
	walk = func(t reflect.Type, depth int) {
		for i := 0; i < t.NumField(); i++ {
			sf := t.Field(i)
			tag := sf.Tag.Get("json")
			if tag == "-" {
				continue
			}
			name, opts, _ := strings.Cut(tag, ",")
			ft := sf.Type
			if sf.Anonymous && name == "" {
				et := ft
				if et.Kind() == reflect.Pointer {
					et = et.Elem()
				}
				if et.Kind() == reflect.Struct {
					if depth == 0 && ft.Kind() == reflect.Struct {
						continue // declared as `extends`, see embedded
					}
					walk(et, depth+1)
					continue
				}
			}
			if !sf.IsExported() {
				continue
			}
			if name == "" {
				name = sf.Name
			}
			f := field{name: name, typ: ft, owner: t.String(), depth: depth,
				optional: hasOpt(opts, "omitempty") || hasOpt(opts, "omitzero")}
			if at, ok := index[name]; ok {
				if out[at].depth > depth {
					out[at] = f
				}
				continue
			}
			index[name] = len(out)
			out = append(out, f)
		}
	}
	walk(t, 0)
	return out
}

// embedded lists the structs t embeds by value: they become the interfaces it extends. (A struct embedded
// through a pointer, or deeper, has its fields flattened into the embedder, as encoding/json does.)
func embedded(t reflect.Type) []reflect.Type {
	var out []reflect.Type
	for i := 0; i < t.NumField(); i++ {
		sf := t.Field(i)
		if sf.Anonymous && sf.Type.Kind() == reflect.Struct && sf.Tag.Get("json") == "" {
			out = append(out, sf.Type)
		}
	}
	return out
}

func hasOpt(opts, want string) bool {
	for _, o := range strings.Split(opts, ",") {
		if o == want {
			return true
		}
	}
	return false
}

func (g *generator) declare(t reflect.Type) (string, error) {
	var b strings.Builder
	var bases []string
	for _, e := range embedded(t) {
		n, err := g.expr(e)
		if err != nil {
			return "", err
		}
		bases = append(bases, n)
	}
	b.WriteString("export interface " + g.names[t])
	if len(bases) > 0 {
		b.WriteString(" extends " + strings.Join(bases, ", "))
	}
	b.WriteString(" {\n")
	body, err := g.body(t, "  ")
	if err != nil {
		return "", err
	}
	b.WriteString(body)
	b.WriteString("}\n")
	return b.String(), nil
}

// body writes the fields of struct t, one per line, indented.
func (g *generator) body(t reflect.Type, indent string) (string, error) {
	var b strings.Builder
	for _, f := range fields(t) {
		key := f.owner + "." + f.name
		ts, ok := g.overrides[key]
		if ok {
			g.used[key] = true
		} else {
			var err error
			if ts, err = g.expr(f.typ); err != nil {
				return "", fmt.Errorf("field %s: %w", f.name, err)
			}
			if f.typ.Kind() == reflect.Pointer && !f.optional {
				ts += " | null"
			}
		}
		ts = strings.ReplaceAll(ts, "\n", "\n"+indent)
		opt := ""
		if f.optional {
			opt = "?"
		}
		fmt.Fprintf(&b, "%s%s%s: %s;\n", indent, quoteKey(f.name), opt, ts)
	}
	return b.String(), nil
}

func quoteKey(k string) string {
	for i, r := range k {
		if !(r == '_' || r == '$' || r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || i > 0 && r >= '0' && r <= '9') {
			return fmt.Sprintf("%q", k)
		}
	}
	return k
}

var (
	timeType = reflect.TypeFor[time.Time]()
	rawType  = reflect.TypeFor[json.RawMessage]()
)

// elem is the TypeScript type of a slice or map element: a nil pointer there is a JSON null.
func (g *generator) elem(t reflect.Type) (string, error) {
	ts, err := g.expr(t)
	if err == nil && t.Kind() == reflect.Pointer {
		ts += " | null"
	}
	return ts, err
}

// expr is the TypeScript type of t (a pointer is its element: nullability belongs to the field).
func (g *generator) expr(t reflect.Type) (string, error) {
	switch {
	case t == timeType:
		return "string", nil
	case t == rawType:
		return "unknown", nil
	}
	switch t.Kind() {
	case reflect.Pointer:
		return g.expr(t.Elem())
	case reflect.Bool:
		return "boolean", nil
	case reflect.String:
		return "string", nil
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Float32, reflect.Float64:
		return "number", nil
	case reflect.Interface:
		return "unknown", nil
	case reflect.Slice, reflect.Array:
		if t.Elem().Kind() == reflect.Uint8 {
			return "string", nil // base64 on the wire
		}
		el, err := g.elem(t.Elem())
		if err != nil {
			return "", err
		}
		if strings.ContainsAny(el, " |&") {
			el = "(" + el + ")"
		}
		return el + "[]", nil
	case reflect.Map:
		if t.Key().Kind() != reflect.String {
			return "", fmt.Errorf("map key %s is not a string", t.Key())
		}
		v, err := g.elem(t.Elem())
		if err != nil {
			return "", err
		}
		return "Record<string, " + v + ">", nil
	case reflect.Struct:
		if t.Name() == "" {
			if len(embedded(t)) > 0 {
				return "", fmt.Errorf("anonymous struct %s embeds a struct: give it a name", t)
			}
			body, err := g.body(t, "  ")
			if err != nil {
				return "", err
			}
			return "{\n" + body + "}", nil // anonymous struct, inline; body re-indents it under its field
		}
		if n, ok := g.names[t]; ok {
			return n, nil
		}
		if !ast.IsExported(t.Name()) {
			return "", fmt.Errorf("%s is unexported: list it as a root to give it a TypeScript name", t)
		}
		if err := g.name(t, t.Name()); err != nil {
			return "", err
		}
		return g.names[t], nil
	}
	return "", fmt.Errorf("cannot map %s to TypeScript", t)
}
